from pathlib import Path
import hashlib,json,re,shutil,tarfile
p=Path('target/alignment-review-20261017');dest=Path('design/reviews/alignment-20261017');dest.mkdir(parents=True,exist_ok=True)
def sha(f):return hashlib.sha256(Path(f).read_bytes()).hexdigest()
def dump(f,v):Path(f).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
checks=json.load(open(p/'checks-final.json'));assert len(checks)==7 and all(c['exit']==0 for c in checks)
rows=re.findall(r'test result: ok\. (\d+) passed; \d+ failed; (\d+) ignored', (p/'tests-final.log').read_text());counts={'passed':sum(int(x) for x,_ in rows),'ignored':sum(int(x) for _,x in rows)}
pixels=json.load(open(p/'pixel-checks.json'));captures=json.load(open(p/'captures/manifest.json'));assert len(captures)==727
interactions=json.load(open(p/'interactions/manifest.json'));assert len(interactions)==63 and all(c['passed'] for c in interactions)
before=json.load(open(p/'before-source.json'));changed=[n for n,h in before.items() if not Path(n).exists() or sha(n)!=h];assert all(Path(n).is_file() for n in before)
expected={'crates/tekes-ui-controls/src/'+n for n in ['chart.rs','layout.rs','layout_view.rs','collections_view.rs','feedback_view.rs']}|{'crates/tekes-ui-gallery/src/gallery/'+n for n in ['mod.rs','workbench.rs','workbench/extended.rs','workbench/extended/collections_adapter.rs','workbench/extended/feedback_adapter.rs','pages/icons.rs','pages/showcase.rs']}|{'crates/tekes-ui-design-export/src/lib.rs','crates/tekes-ui-design-export/src/proposal.rs','docs/gallery.md'}
assert set(changed)<=expected,(set(changed)-expected)
assert sha('crates/tekes-ui-controls/src/widgets.rs')=='4caf513a069f12acef2d85c3796655ed6a5f9d2c5a94a0d95fd90f74e5ffb4ff'
old=json.load(open('target/remaining-components-20261017/final-source.json'));layout=json.load(open('design/source/layout.json'));layout.pop('alignment');assert hashlib.sha256((json.dumps(layout,ensure_ascii=False,indent=2)+'\n').encode()).hexdigest()==old['design/source/layout.json']
design_changes=[n for n,h in old.items() if n.startswith('design/') and not n.startswith('design/reviews/') and sha(n)!=h];assert set(design_changes)=={'design/source/layout.json','design/tokens.json'}
source={str(f):sha(f) for root in ['crates','design','docs'] for f in Path(root).rglob('*') if f.is_file() and 'target' not in f.parts and 'reviews' not in f.parts};assert source==json.load(open(p/'frozen-source.json')), 'Production sources changed during final verification'
dump(p/'final-source.json',source)
with tarfile.open(dest/'changed-sources.tar.gz','w:gz') as t:
 for n in changed+design_changes:t.add(n,arcname=n)
